commands:
set -eu
echo SMOKE_EVENT_ROW
k3s kubectl exec -n phantom deployment/phantom-postgres -- psql -U phantom -d phantom -Atc "SELECT event_id,event_type,comm,namespace,pod_name,container_name,container_id,image_digest,COALESCE(sbom_id::text,''),COALESCE(purl,''),COALESCE(binding_status,''),received_at::text FROM drift_events WHERE event_id='0000012e-1404-2112-0000-000000000001';"
echo SBOM_RECORDS_FOR_TARGET_DIGEST
k3s kubectl exec -n phantom deployment/phantom-postgres -- psql -U phantom -d phantom -Atc "SELECT count(*) FROM phantom_sbom.sboms WHERE image_digest='sha256:50a337a6c7f43a609feaa56e826e4b5085db9f95447f3232edbe47302c7b0ad7';"
echo SAME_EVENT_IN_CANONICAL_STREAM
k3s kubectl exec -n phantom deployment/phantom-api-gateway -- python3 -c "import json,redis; c=redis.Redis(host='phantom-redis',port=6379,decode_responses=True); target='0000012e-1404-2112-0000-000000000001'; found=[];
for sid,f in c.xrange('phantom:drift-events'):
 e=json.loads(f['event']);
 if e.get('event_id')==target: found.append((sid,f.get('schema_version'),e))
print('matches='+str(len(found)));
[print('stream_id='+s+' schema='+v+' event_id='+e['event_id']+' event_type='+e['event_type']+' workload='+e['workload'].get('namespace')+'/'+e['workload'].get('pod_name')+' image_digest='+e['workload'].get('image_digest')+' sbom_binding='+str(e.get('sbom_binding'))) for s,v,e in found]"
echo CONSUMER_METRIC
k3s kubectl exec -n phantom deployment/phantom-api-gateway -- python3 -c "import json,urllib.parse,urllib.request; q=urllib.parse.urlencode({'query':'phantom_redis_stream_messages_total{result=\"success\",stream=\"phantom:drift-events\"}'}); d=json.load(urllib.request.urlopen('http://prometheus.monitoring.svc.cluster.local:9090/api/v1/query?'+q,timeout=5)); [print(x['metric'],x['value'][1]) for x in d.get('data',{}).get('result',[])]"
